pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // minimal helper that accepts the low-level call and returns true (mimics ERC20 transferFrom signature)
    contract Helper {
        // provide a function with the selector transferFrom(address,address,uint256)
        function transferFrom(address, address, uint256) external pure returns (bool) {
            return true;
        }
    }

    Helper h;

    function setUp() public { c = new C(); h = new Helper(); }

    // fuzz parameters: from address and an array length indicator and a dummy uint value
    // We cannot fuzz an address with code, so we deploy Helper and pass its address as caddress.
    function testFuzz_property(address from, uint8 tosLen, uint256 v) public {
        // keep tosLen in a reasonable range but allow 1..10 to be fuzzed
        uint256 len = bound(tosLen, 1, 10);
        // build an array of addresses to pass; contents don't matter because helper ignores them
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            // fill with arbitrary addresses derived from 'from' to be varied by fuzzer
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, i, v)))));
        }

        // call the transfer and capture whether it returns or reverts
        bool ok;
        try c.transfer(from, address(h), tos, v) returns (bool ret) {
            // record the returned boolean
            ok = ret;
        } catch {
            ok = false; // if it reverts, treat as false for observing non-returning behaviour
        }

        // General property: reference implementation always returns true on non-reverting inputs.
        // We assert that the call returned true (ok == true). This holds for the reference C for all inputs,
        // but the mutant (which returns false) will cause this assertion to fail for some inputs.
        assertTrue(ok);
    }
}

