// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // We fuzz: the 'from' address, the number of tos (as uint8 to keep array sizing reasonable), and a value v
    function testFuzz_property(address from, uint8 nTos, uint256 v) public {
        // Keep number of tos non-zero (function requires _tos.length > 0) and reasonably bounded
        uint256 len = uint256(bound(nTos, 1, 8));

        // Build an array of recipient addresses. Use a simple helper deployed below that always succeeds on the low-level call.
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            // deploy a fresh helper for each recipient to ensure there is code at the address
            AdversaryHelper h = new AdversaryHelper();
            tos[i] = address(h);
        }

        // Call transfer and capture whether it returns/doesn't revert. The reference always returns true when it completes.
        bool ok;
        try c.transfer(from, address(tos[0]), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // Single assertion: on the reference implementation any non-reverting call to transfer returns true.
        // We therefore assert that if the call completed (ok boolean observed), it is equal to true.
        // Note: if the call reverted, ok==false and the assertion still holds because the reference never returns false on completion.
        assertTrue(ok);
    }
}

// Helper contract that accepts the low-level call and returns true (does not revert).
contract AdversaryHelper {
    // Accept any calldata and return true for compatibility with reference contract's expectations.
    fallback() external payable {
        // do nothing, implicitly succeeds
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    // fuzz the caller (from), a number of tos to generate, and a uint v
    function testFuzz_property(address from, uint16 tosCount, uint256 v) public {
        // keep tosCount in a reasonable but wide bound (>0 to satisfy require in C)
        tosCount = uint16(bound(tosCount, 1, 10));

        // build an array of distinct recipient addresses (use addresses of deployed simple acceptor contracts)
        address[] memory tos = new address[](tosCount);
        for (uint i = 0; i < tosCount; i++) {
            // deploy a minimal acceptor that always returns true on the expected selector
            tos[i] = address(new Accepting());
        }

        // deploy a callee that implements transferFrom(address,address,uint256) and succeeds
        Callee cal = new Callee();

        // call transfer on c; the rule: for any admissible inputs (tosCount>0 and callee that succeeds),
        // the reference implementation returns true when the call completes (does not revert).
        // We observe this by calling and capturing whether it returned true (without revert) via try/catch
        bool ok;
        try c.transfer(from, address(cal), tos, v) returns (bool ret) {
            // if it returned, check the returned boolean
            ok = ret;
        } catch {
            // if it reverted, mark as false (but admissible inputs shouldn't revert because callee succeeds)
            ok = false;
        }

        // Single assertion: reference contract should always return true (ok==true) for these admissible inputs;
        // the mutant that negates the final returned boolean will make this assertion fail for some inputs.
        assertTrue(ok);
    }
}

// Minimal callee that provides transferFrom and always returns successfully
contract Callee {
    // conform to transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

// Minimal Accepting helper (not strictly necessary for this scenario but kept minimal in case of extensions)
contract Accepting {
    fallback() external payable {}
}
